#include <cstdio>
#include <vector>
#include <queue>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    std::vector<std::vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<char> seen(n + 1, 0);
    int cnt = 0;
    for (int s = 1; s <= n; ++s) {
        if (seen[s]) continue;
        ++cnt;
        std::queue<int> q;
        q.push(s);
        seen[s] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) if (!seen[v]) { seen[v] = 1; q.push(v); }
        }
    }
    printf("%d\n", cnt);
    return 0;
}
